Create a Health Insurance Quote > OpenAPI definition #/components/schemas/AEInsuranceServiceRating

{
  "type": "object",
  "required": [
    "FinancialStrength",
    "ClaimsServicePerformance",
    "CustomerServiceComplaintHandling",
    "PolicyDigitalConvenience"
  ],
  "properties": {
    "FinancialStrength": {
      "type": "object",
      "properties": {
        "SolvencyRatio": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsuranceServiceRatingRateOrRatio"
            }
          ],
          "description": "The Solvency Capital Requirement (SCR) is a measure used to determine the minimum amount of capital that insurance companies must hold to ensure they can meet their obligations even under extreme financial stress."
        },
        "YearsInBusiness": {
          "type": "integer",
          "description": "The length of time the insurer LFI has been licensed in the UAE market to provide the type of insurance requested in the quote"
        }
      },
      "required": [
        "SolvencyRatio",
        "YearsInBusiness"
      ],
      "description": "Key indicators to assess the financial strength and stability of the insurer LFI in terms of their ability to meet obligations to policyholders.",
      "additionalProperties": false
    },
    "ClaimsServicePerformance": {
      "type": "object",
      "properties": {
        "AverageClaimSettlementTime": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsuranceServiceRatingRateOrRatio"
            }
          ],
          "description": "Represents the average number of calendar days taken by the insurer to settle (pay) a claim, measured from the date the claim was filed, for the specific type of insurance coverage requested in this quote."
        },
        "ClaimSettlementRatio": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsuranceServiceRatingPercentage"
            }
          ],
          "description": "Indicates the percentage of claims successfully paid by the insurer (LFI) out of the total number of claims filed for the type of insurance coverage requested in this quote."
        },
        "ClaimRejectionRate": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsuranceServiceRatingPercentage"
            }
          ],
          "description": "Represents the percentage of claims that were rejected or denied by the insurer (LFI) relative to the total number of claims received for the type of insurance coverage requested in this quote."
        },
        "ClaimsPaymentCapacityRatio": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsuranceServiceRatingRateOrRatio"
            }
          ],
          "description": "Indicates the insurer’s short-term ability to meet claims obligations using its liquid assets. The calculation is: Liquid assets divided by total claims payable."
        }
      },
      "required": [
        "AverageClaimSettlementTime",
        "ClaimSettlementRatio",
        "ClaimRejectionRate",
        "ClaimsPaymentCapacityRatio"
      ],
      "description": "Provides performance metrics related to the insurer’s claims handling process for the specified insurance type.",
      "additionalProperties": false
    },
    "CustomerServiceComplaintHandling": {
      "type": "object",
      "properties": {
        "CustomerComplaintRate": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsuranceServiceRatingRateOrRatio"
            }
          ],
          "description": "Indicates the number of customer complaints received per 1,000 active policies for the type of insurance requested in this quote."
        },
        "ComplaintResolutionTime": {
          "type": "integer",
          "description": "Represents the average number of calendar days taken to resolve a customer complaint, measured from the date it was lodged, for the type of insurance requested in this quote."
        },
        "NetPromoterScore": {
          "type": "integer",
          "minimum": -100,
          "maximum": 100,
          "description": "A customer satisfaction metric that reflects how likely customers are to recommend the insurer (LFI) to others for the type of insurance requested in this quote. Scores range from -100 to +100."
        }
      },
      "required": [
        "CustomerComplaintRate",
        "ComplaintResolutionTime",
        "NetPromoterScore"
      ],
      "description": "Represents key customer service metrics and complaint handling indicators for the specific type of insurance requested in the quote. These measures reflect the insurers responsiveness, resolution efficiency, and customer sentiment.",
      "additionalProperties": false
    },
    "PolicyDigitalConvenience": {
      "type": "object",
      "properties": {
        "InstantDigitalPolicyIssuance": {
          "type": "boolean",
          "description": "Indicates whether the insurer supports instant or fully digital policy issuance for the specific type of insurance requested in the quote. A value of true means the policy can be issued immediately online upon purchase."
        },
